def RK(rid, cat, title, desc, li, im, mit, gates, owner, status="OPEN", ev=""):
    s = li * im
    sev = "CRITICAL" if s >= 20 else "HIGH" if s >= 12 else "MEDIUM" if s >= 6 else "LOW"
    return dict(risk_id=rid, category=cat, title=title, description=desc, likelihood=str(li), impact=str(im), severity=sev,
                mitigation_tasks=mit, gates=gates, owner=owner, status=status, evidence=ev)
